mapper.update:
UPDATE student
SET name = #{name}, email = #{email,jdbcType=VARCHAR}, github_url = #{githubUrl,jdbcType=VARCHAR},
    desired_job = #{desiredJob,jdbcType=VARCHAR}, preferred_region = #{preferredRegion,jdbcType=VARCHAR}
WHERE id = #{studentId}

UPDATE student
SET skills = #{skills,jdbcType=VARCHAR,typeHandler=com.ieum.common.mybatis.JsonTypeHandler}
WHERE id = #{studentId}

UPDATE student_project
SET portfolio_file_url = #{fileName,jdbcType=VARCHAR}, include_in_apply = #{include}, source = 'USER'
WHERE student_id = #{studentId} AND id = #{itemId}
